import { PlaywrightCrawler, log } from 'crawlee';
import { chromium } from 'playwright-extra';
import StealthPlugin from 'puppeteer-extra-plugin-stealth';

// 1. AKTIFKAN CLOAK / STEALTH PLUGIN
// Ini akan menyembunyikan fingerprint Playwright, reCAPTCHA v3, Canvas, & WebGL
chromium.use(StealthPlugin());

// Matikan log bawaan Crawlee agar output bersih
log.setLevel(log.LEVELS.OFF);

export async function scrapeGeminiStealth(promptText) {
    let aiResult = '';

    const crawler = new PlaywrightCrawler({
        headless: true,
        requestHandlerTimeoutSecs: 90,
        navigationTimeoutSecs: 45,

        launchContext: {
            // Gunakan Launcher Chromium yang sudah dibungkus Stealth/Cloak
            launcher: chromium,
            launchOptions: {
                args: [
                    '--no-sandbox',
                    '--disable-setuid-sandbox',
                    '--disable-dev-shm-usage',
                    '--disable-blink-features=AutomationControlled',
                    '--disable-web-security',
                    '--disable-features=IsolateOrigins,site-per-process'
                ],
            },
            // Chrome User-Agent Asli
            userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36',
        },

        async requestHandler({ page }) {
            // 2. Extra Cloaking Injection (Pembersihan flag navigator)
            await page.addInitScript(() => {
                Object.defineProperty(navigator, 'webdriver', { get: () => undefined });
                Object.defineProperty(navigator, 'languages', { get: () => ['id-ID', 'id', 'en-US', 'en'] });
            });

            // Set Header Bahasa Indonesia
            await page.setExtraHTTPHeaders({
                'accept-language': 'id-ID,id;q=0.9,en-US;q=0.8,en;q=0.7',
            });

            // 3. Buka Gemini Web Guest Mode
            await page.goto('https://gemini.google.com', { waitUntil: 'domcontentloaded' });

            // 4. Cari & Isi Input Text
            const inputSelector = 'div[contenteditable="true"], rich-textarea p, textarea';
            await page.waitForSelector(inputSelector, { timeout: 20000 });

            // Simulasikan klik & mengetik seperti manusia
            await page.click(inputSelector);
            await page.keyboard.type(promptText, { delay: 30 });
            await page.waitForTimeout(500);

            // Kirim Prompt
            await page.keyboard.press('Enter');

            // 5. Tunggu Respon AI
            const responseSelector = 'message-content, .model-response-text, .response-container-content';
            await page.waitForSelector(responseSelector, { timeout: 30000 });

            // Beri jeda 4 detik agar generasi teks streaming selesai
            await page.waitForTimeout(4000);

            // 6. Ekstrak Hasil
            aiResult = await page.evaluate((sel) => {
                const nodes = document.querySelectorAll(sel);
                if (nodes.length > 0) {
                    return nodes[nodes.length - 1].textContent.trim();
                }
                return '';
            }, responseSelector);
        },
    });

    await crawler.run(['https://gemini.google.com']);
    return aiResult;
}

// === CARA MENJALANKAN SCRIPT ===
const prompt = process.argv[2] || 'Hallo siapa lu?';

scrapeGeminiStealth(prompt)
    .then((reply) => {
        console.log(reply || '❌ Gagal mengambil jawaban dari DOM (Terdeteksi Captcha/Timeout).');
    })
    .catch((err) => {
        console.error('❌ Scrape Error:', err.message);
    });

