import { PlaywrightCrawler, log } from 'crawlee';
import { chromium } from 'playwright-extra';
import StealthPlugin from 'puppeteer-extra-plugin-stealth';

// 1. AKTIFKAN CLOAK / STEALTH PLUGIN
// Ini akan menyembunyikan fingerprint Playwright, reCAPTCHA v3, Canvas, & WebGL
chromium.use(StealthPlugin());

// Matikan log bawaan Crawlee agar output bersih
log.setLevel(log.LEVELS.OFF);

export async function scrapeChatGPTStealth(promptText) {
    let aiResult = '';

    const crawler = new PlaywrightCrawler({
        headless: true,
        requestHandlerTimeoutSecs: 120, // Mungkin butuh waktu lebih lama untuk ChatGPT
        navigationTimeoutSecs: 60, // Waktu navigasi yang cukup

        launchContext: {
            // Gunakan Launcher Chromium yang sudah dibungkus Stealth/Cloak
            launcher: chromium,
            launchOptions: {
                args: [
                    '--no-sandbox',
                    '--disable-setuid-sandbox',
                    '--disable-dev-shm-usage',
                    '--disable-blink-features=AutomationControlled',
                    '--disable-web-security',
                    '--disable-features=IsolateOrigins,site-per-process'
                ],
            },
            // Chrome User-Agent Asli
            userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36', // User agent yang umum
        },

        async requestHandler({ page }) {
            // 2. Extra Cloaking Injection (Pembersihan flag navigator)
            await page.addInitScript(() => {
                Object.defineProperty(navigator, 'webdriver', { get: () => undefined });
                Object.defineProperty(navigator, 'languages', { get: () => ['en-US', 'en', 'id-ID', 'id'] }); // Sesuaikan bahasa jika perlu
            });

            // Set Header Bahasa (sesuaikan jika perlu)
            await page.setExtraHTTPHeaders({
                'accept-language': 'en-US,en;q=0.9,id-ID;q=0.8,id;q=0.7', // Default bahasa Inggris biasanya lebih aman untuk AI global
            });

            // 3. Buka ChatGPT Web (Pastikan URL benar, bisa berubah)
            // Menggunakan URL chat.openai.com karena ini yang paling umum
            await page.goto('https://chat.openai.com', { waitUntil: 'domcontentloaded' });

            // --- Proses Login atau Skip Login ---
            // ChatGPT seringkali butuh login. Ini bagian yang paling tricky.
            // Kamu mungkin perlu menambahkan logika untuk login otomatis (dengan email/password)
            // atau mendeteksi apakah halaman login muncul dan menanganinya.
            // Untuk contoh ini, kita asumsikan user sudah login atau bisa melewati login.
            // Jika tidak, scraper akan berhenti di sini.
            // PENTING: Menyimpan kredensial login secara aman sangat krusial!
            // Contoh sederhana (JANGAN SIMPAN LANGSUNG DI KODE UNTUK PRODUKSI):
