// === CARA MENJALANKAN SCRIPT ===
// Contoh menjalankan dari command line: node nama_file_ini.cjs "Halo ChatGPT, siapa kamu?"
const prompt = process.argv[2] || 'Halo, siapa kamu?'; // Prompt default jika tidak ada argumen

scrapeChatGPTStealth(prompt)
    .then((reply) => {
