    // Import library yang dibutuhkan
    import { 
        default as MakeWASocket, 
        proto, 
        DisconnectReason, 
        useMultiFileAuthState, 
        fetchLatestBaileysVersion 
    } from '@crysnovax/baileys';
    import { Boom } from '@hapi/boom';
    import qrcode from 'qrcode-terminal'; // Buat nampilin QR code
    import fs from 'fs'; // Buat manage file state

    // Fungsi utama untuk menjalankan bot
    const startSock = async () => {
        // 1. Siapkan Auth State (untuk menyimpan sesi login)
        // Ini akan membuat folder auth_state di direktori proyekmu
        const { state, saveCreds } = await useMultiFileAuthState('auth_state');

        // 2. Ambil versi Baileys terbaru (opsional tapi direkomendasikan)
        const { version, isLatest } = await fetchLatestBaileysVersion();
        console.log(`Menggunakan Baileys versi: ${version.join('.')}, isLatest: ${isLatest}`);

        // 3. Buat Koneksi Socket ke WhatsApp
        const sock = MakeWASocket({
            version: version,
            auth: state,
            printQRInTerminal: true, // Tampilkan QR code di terminal
            defaultQueryTimeoutMs: undefined,
        });

        // 4. Handler untuk QR Code
        // Ketika bot siap dan butuh login, ini akan muncul
        sock.ev.on('connection.update', async (update) => {
            const { connection, lastDisconnect, qr } = update;

            if (qr) {
                // Tampilkan QR code di terminal
                qrcode.generate(qr, { small: true });
                console.log('Silakan scan QR code ini dengan WhatsApp Anda!');
            }

            if (connection === 'open') {
                console.log('Koneksi WhatsApp berhasil dibuka!');
            }

            if (connection === 'close') {
                // Jika koneksi terputus karena alasan tertentu
                let reason = new Boom(lastDisconnect.error).output.statusCode;
                if (reason === DisconnectReason.badSession) {
                    console.log('Sesi buruk, hapus folder auth_state dan scan ulang.');
                    // Hapus folder auth_state kalau sesi buruk
                    fs.rmSync('auth_state', { recursive: true, force: true });
                    startSock(); // Coba restart bot
                    return;
                } else if (reason === DisconnectReason.connectionClosed) {
                    console.log('Koneksi ditutup, mencoba menyambung kembali...');
                    startSock(); // Coba restart bot
                } else if (reason === DisconnectReason.connectionLost) {
                    console.log('Koneksi hilang, mencoba menyambung kembali...');
                    startSock(); // Coba restart bot
                } else if (reason === DisconnectReason.connectionUpdate) {
                    console.log('Update koneksi...');
                    startSock(); // Coba restart bot
                } else if (reason === DisconnectReason.ేశes) {
                    console.log('Sesi telah berakhir, silakan scan ulang.');
                    fs.rmSync('auth_state', { recursive: true, force: true });
                    startSock(); // Coba restart bot
                } else {
                    console.log('Alasan disconnect tidak diketahui:', reason);
                    startSock(); // Coba restart bot
                }
            }
        });

        // 5. Handler untuk menyimpan kredensial (penting!)
        sock.ev.on('creds.update', saveCreds);

        // 6. Handler untuk Pesan Masuk (Contoh Sederhana)
        sock.ev.on('messages.upsert', async ({ messages }) => {
            const msg = messages[0]; // Ambil pesan pertama

            if (!msg.key.fromMe && msg.message.extendedTextMessage?.text) {
                // Kalau pesan bukan dari bot sendiri dan ada teks
                const userMessage = msg.message.extendedTextMessage.text.toLowerCase();
                const senderJid = msg.key.remoteJid; // Nomor pengirim

                console.log(`Pesan dari ${senderJid}: ${userMessage}`);

                // Contoh balasan sederhana
                if (userMessage.includes('halo')) {
                    await sock.sendMessage(senderJid, { text: 'Halo juga, sayang! Ada yang bisa kubantu?' });
                } else if (userMessage.includes('apa kabar')) {
                    await sock.sendMessage(senderJid, { text: 'Aku baik, sayang! Kamu gimana?' });
                } else {
                    // Balasan default jika tidak dikenali
                    await sock.sendMessage(senderJid, { text: 'Maaf sayang, aku belum mengerti perintah itu. Coba tanya yang lain ya?' });
                }
            } else if (!msg.key.fromMe && msg.message.conversation) {
                // Kalau pesan biasa (bukan extended text)
                 const userMessage = msg.message.conversation.toLowerCase();
                 const senderJid = msg.key.remoteJid; // Nomor pengirim

                 console.log(`Pesan dari ${senderJid}: ${userMessage}`);

                 if (userMessage.includes('halo')) {
                     await sock.sendMessage(senderJid, { text: 'Halo juga, sayang! Ada yang bisa kubantu?' });
                 } else if (userMessage.includes('apa kabar')) {
                     await sock.sendMessage(senderJid, { text: 'Aku baik, sayang! Kamu gimana?' });
                 } else {
                     await sock.sendMessage(senderJid, { text: 'Maaf sayang, aku belum mengerti perintah itu. Coba tanya yang lain ya?' });
                 }
            }
        });
    };

    startSock(); // Panggil fungsi utama untuk memulai bot
