import { PlaywrightCrawler, log } from 'crawlee';
import { chromium } from 'playwright-extra';
import StealthPlugin from 'puppeteer-extra-plugin-stealth';
import cheerio from 'cheerio'; // Untuk parse HTML

// 1. AKTIFKAN CLOAK / STEALTH PLUGIN
chromium.use(StealthPlugin());
log.setLevel(log.LEVELS.OFF); // Matikan log bawaan Crawlee agar output bersih

// Fungsi utama untuk scrape
export async function scrapeKomikuMangaList(baseUrl = 'https://komiku.org/') {
    let mangaList = []; // Array untuk menyimpan data manga

    const crawler = new PlaywrightCrawler({
        headless: true,
        requestHandlerTimeoutSecs: 180, // Waktu timeout lebih lama untuk scraping
        navigationTimeoutSecs: 90,

        launchContext: {
            launcher: chromium,
            launchOptions: {
                args: [
                    '--no-sandbox',
                    '--disable-setuid-sandbox',
                    '--disable-dev-shm-usage',
                    '--disable-blink-features=AutomationControlled',
                    '--disable-web-security',
                    '--disable-features=IsolateOrigins,site-per-process'
                ],
            },
            userAgent: 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36', // User agent yang umum
        },

        async requestHandler({ page, enqueueLinks }) {
            // 2. Extra Cloaking Injection
            await page.addInitScript(() => {
                Object.defineProperty(navigator, 'webdriver', { get: () => undefined });
                Object.defineProperty(navigator, 'languages', { get: () => ['id-ID', 'id', 'en-US', 'en'] });
            });
            await page.setExtraHTTPHeaders({ 'accept-language': 'id-ID,id;q=0.9,en-US;q=0.8,en;q=0.7' });

            // 3. Buka Halaman Utama Komiku.org
            await page.goto(baseUrl, { waitUntil: 'domcontentloaded' });
            await page.waitForTimeout(3000); // Jeda sebentar agar halaman siap

            // --- Handle Cookie Consent (Penting!) ---
            // Website manga sering punya pop-up cookie
            try {
                // Selector ini perlu dicari di inspect element komiku.org
                const acceptCookiesSelector = 'button[onclick*="acceptCookie"]'; // Contoh selector, perlu diverifikasi
                await page.waitForSelector(acceptCookiesSelector, { timeout: 10000, visible: true });
                await page.click(acceptCookiesSelector);
                console.log('Cookie accepted.');
            } catch (error) {
                console.log('Cookie consent not found or already accepted.');
            }
            // --- End Handle Cookie Consent ---

            // 4. Cari Elemen yang Berisi Daftar Manga (Judul dan Link)
            // Selector ini juga perlu kamu cari di inspect element komiku.org
            // Biasanya ada di dalam list atau div tertentu
            const mangaItemSelector = 'div.list-update a.list-title'; // Contoh selector, perlu dicek!
            await page.waitForSelector(mangaItemSelector, { timeout: 30000 });
            await page.waitForTimeout(4000); // Jeda agar data terload

            // 5. Ekstrak Data Manga
            const mangas = await page.$$eval(mangaItemSelector, (elements) => {
                return elements.map(el => {
                    const title = el.textContent.trim();
                    const url = el.href;
                    return { title, url };
                });
            });

            mangaList.push(...mangas);

            // Kalau mau scrape halaman selanjutnya, bisa pakai enqueueLinks
            // Tapi untuk contoh ini, kita ambil dari halaman pertama saja.
        },
    });

    // Mulai crawling dari halaman utama
    await crawler.run([baseUrl]);
    return mangaList;
}

// === CARA MENJALANKAN SCRIPT ===
